          "يظهر هنا مثال مضاد: الحساب بالأعداد الخام يجعل الجلستين الأولى والثالثة أقرب إقليديًا من الأولى والثانية، لأن طول الجلسة الثانية أكبر كثيرًا. أما العمل بالنسب فيجعل الأولى والثانية متطابقتين على هذه السمات. إذا كان طول الجلسة مهمًا للقرار، يمكن تمثيله بعمود منفصل ومراجعة وزنه. وتحتاج الجلسة التي لا تحتوي على مشاهدة صالحة إلى قاعدة واضحة قبل القسمة.",
