          "ومن المفيد أن تسأل من سيتولى إصلاح العطل ومتى يمكن استبدال الإصدار. في الخدمة المستضافة قد يدير المزوّد الإصدارات، وقد يقدم طريقة لاختيار إصدار بعينه. في التشغيل المحلي تتحكم المؤسسة في موعد التحديث، وعليها الاحتفاظ بملفات العمل ومراجعة التغييرات قبل التحويل. تظهر هذه التكاليف بعد التجربة الأولى، لذلك يحسن إدخالها في المقارنة مبكرًا."
